import{_ as s,o as t,c as i,ag as e}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"SetBlendParam 设置路径过渡方式","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetBlendParam.md","filePath":"3. 指令/5. 设置指令/SetBlendParam.md","lastUpdated":1778862643000}'),n={name:"3. 指令/5. 设置指令/SetBlendParam.md"};function r(l,a,h,d,o,p){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="setblendparam-设置路径过渡方式" tabindex="-1">SetBlendParam 设置路径过渡方式 <a class="header-anchor" href="#setblendparam-设置路径过渡方式" aria-label="Permalink to &quot;SetBlendParam 设置路径过渡方式&quot;">​</a></h1><p>该指令用于<strong>全局设置机器人路径运动的过渡（平滑）方式</strong>。它决定了机器人在经过中间点时，是必须精确停顿（精确定位），还是以圆滑的曲线掠过（连续轨迹控制）。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetBlendParam(B, C) SetBlendParam(过渡类型, 过渡值)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>B：过渡类型（BlendType）</td><td>enum（枚举型）</td><td>定义机器人接近目标点时的动作逻辑。<br>* <strong>FINE</strong>：<strong>无过渡（精确定位）</strong>。机器人必须完全到达目标点，速度降为 0 且确认位置偏差在允许范围内后，才开始下一段运动。<br>* <strong>RELATIVE</strong>：<strong>相对过渡</strong>。根据当前的运动参数（速度、加速度等）自动计算转弯半径。<br>* <strong>ABSOLUTE</strong>：<strong>绝对过渡</strong>。机器人严格按照参数 <strong>C</strong> 设定的物理尺寸进行转弯。</td><td></td></tr><tr><td>C：过渡值（BlendValue）</td><td>ZONE（通常为 C0 - C100 或具体的距离数值）</td><td>定义开始&quot;切角&quot;转弯的时机。数值越大，转弯的半径越大，轨迹越圆滑，速度损失越小；数值越小，越接近目标点才开始转弯。</td><td>若缺省，系统通常默认为 <strong>C100</strong>。</td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p><code>SetBlendParam</code> 是一个<strong>状态设定指令</strong>。在搬运或涂胶任务中，如果每个点都用 <code>FINE</code>，机器人会频繁顿挫；使用 <code>RELATIVE</code> 或 <code>ABSOLUTE</code> 则能让机器人像赛车过弯一样，不停车直接平滑通过。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetBlendParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C50)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P2, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>执行结果：</strong></p><p>机器人在经过 <strong>P1</strong> 点时，不会完全停死，而是在距离 P1 点一定范围（由 C50 决定）时就开始向 <strong>P2</strong> 偏转，从而保持运动的连续性。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>高速搬运</strong>：使用 <code>RELATIVE</code> 过渡，减少由于加减速带来的机械冲击，大幅缩短节拍时间。</li><li><strong>连续轨迹工艺</strong>：在涂胶、打磨或喷涂作业中，必须使用过渡指令，否则会在拐角处堆积胶水或造成过度磨损。</li><li><strong>精准装配</strong>：在最后插拔或放置工件的终点，通常临时切换为 <code>FINE</code> 以确保位置精度。</li></ul>`,18)])])}const E=s(n,[["render",r]]);export{g as __pageData,E as default};
